        /// <summary>
    /// MPJ_2864_CreditLimitBalance 03/11/2021
    /// Caption visible according to FSD 2864
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METPopulateCustCreditLimitService));
        this.parmMethodName(methodStr(METPopulateCustCreditLimitService, processOperation));
        this.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        this.parmDialogCaption("@MET:CustCreditLimitActionMenuItem");
    }

/// <summary>
/// MPJ_2864_CreditLimitBalance 03/11/2021
/// Automatically populates the batch text required by user before submitting to batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:CustCreditLimitBatchDesc";
}

    /// <summary>
    /// MPJ_2864_CreditLimitBalance 03/11/2021
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METPopulateCustCreditLimitController controller;

        controller = new METPopulateCustCreditLimitController();
        controller.parmArgs(args);

        controller.startOperation();
        
    }

/// <summary>
/// MPJ_2864 - kscerri - 22/03/2021
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METPopulateCustCreditLimitController construct()
{
    return new METPopulateCustCreditLimitController();
}
